"""Core immutable map and mutable fleet entities."""

from __future__ import annotations

from dataclasses import dataclass, field

Position = tuple[int, int]


@dataclass(frozen=True, slots=True)
class GridMap:
    width: int
    height: int
    obstacles: frozenset[Position] = frozenset()

    def __post_init__(self) -> None:
        if self.width <= 0 or self.height <= 0:
            raise ValueError("map dimensions must be positive")
        if any(not self.contains(cell) for cell in self.obstacles):
            raise ValueError("obstacle lies outside the map")

    def contains(self, position: Position) -> bool:
        x, y = position
        return 0 <= x < self.width and 0 <= y < self.height

    def traversable(self, position: Position) -> bool:
        return self.contains(position) and position not in self.obstacles

    def neighbors(self, position: Position) -> tuple[Position, ...]:
        x, y = position
        candidates = ((x, y - 1), (x - 1, y), (x + 1, y), (x, y + 1))
        return tuple(candidate for candidate in candidates if self.traversable(candidate))


@dataclass(slots=True)
class Task:
    task_id: str
    pickup: Position
    dropoff: Position
    assigned_robot: str | None = None
    picked_up: bool = False
    completed: bool = False


@dataclass(slots=True)
class Robot:
    robot_id: str
    position: Position
    route: list[Position] = field(default_factory=list)
    task_id: str | None = None
    distance_travelled: int = 0

    @property
    def idle(self) -> bool:
        return self.task_id is None

"""Deterministic shortest-path search for four-way warehouse grids."""

from __future__ import annotations

from collections import deque

from .model import GridMap, Position


def shortest_path(grid: GridMap, start: Position, goal: Position) -> list[Position]:
    """Return positions after *start* through *goal*, or raise when unreachable."""
    if not grid.traversable(start) or not grid.traversable(goal):
        raise ValueError("path endpoint is not traversable")
    if start == goal:
        return []
    queue = deque([start])
    previous: dict[Position, Position | None] = {start: None}
    while queue:
        current = queue.popleft()
        for neighbor in grid.neighbors(current):
            if neighbor in previous:
                continue
            previous[neighbor] = current
            if neighbor == goal:
                queue.clear()
                break
            queue.append(neighbor)
    if goal not in previous:
        raise ValueError(f"no route from {start} to {goal}")
    path: list[Position] = []
    cursor = goal
    while cursor != start:
        path.append(cursor)
        parent = previous[cursor]
        if parent is None:
            raise RuntimeError("broken predecessor chain")
        cursor = parent
    path.reverse()
    return path

